.ds .ds-token-border i { width:var(--p-control-size-sm); height:var(--p-control-size-sm); border-radius:var(--p-inner-radius); border:var(--p-border-width) solid currentColor; }
.ds .ds-token-border [data-token="strong"] { border-width:var(--p-border-width-strong); }
.ds .ds-token-border [data-token="focus"] { border:0; outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset-tight); }
